        {
          h: 'Характеристики колебаний',
          html: String.raw`<p><b>Колебания</b> — движения, которые повторяются через равные промежутки времени. Характеристики:</p>
<ul>
<li><b>амплитуда</b> $A$ — наибольшее отклонение от положения равновесия;</li>
<li><b>период</b> $T$ — время одного полного колебания: $T = t/N$;</li>
<li><b>частота</b> $\nu = 1/T$ — число колебаний в секунду, единица — герц (Гц);</li>
<li><b>циклическая частота</b> $\omega = 2\pi\nu = 2\pi/T$, рад/с.</li>
</ul>
<p>Гармонические колебания описываются законом $x = A\cos(\omega t + \varphi_0)$. Из уравнения сразу читаются амплитуда и $\omega$: например, для $x = 0{,}05\cos(10\pi t)$ имеем $A = 5$ см, $\omega = 10\pi$ рад/с, $\nu = 5$ Гц, $T = 0{,}2$ с.</p>
<div class="trap">За один период тело проходит путь $4A$, а не $A$ и не $2A$: от равновесия до края, обратно, до другого края и снова в равновесие. За половину периода — $2A$.</div>
<div class="quick" data-a="2">Маятник совершил 30 колебаний за 60 с. Чему равен период колебаний (в секундах)?</div>`
        },
        {
          h: 'Маятники',
          html: String.raw`<div class="rule">
$$T_{мат} = 2\pi\sqrt{\dfrac{l}{g}} \qquad\qquad T_{пруж} = 2\pi\sqrt{\dfrac{m}{k}}$$
</div>
<p>Что важно для заданий «как изменится»:</p>
<table class="tbl">
<tr><th>Изменение</th><th>Математический</th><th>Пружинный</th></tr>
<tr><td>Масса груза ×4</td><td>не изменится</td><td>период ×2</td></tr>
<tr><td>Длина нити ×4</td><td>период ×2</td><td>—</td></tr>
<tr><td>Перенести на Луну</td><td>период увеличится</td><td>не изменится</td></tr>
<tr><td>Амплитуда ×2 (малые колебания)</td><td>не изменится</td><td>не изменится</td></tr>
</table>
<p><b>Энергия.</b> При колебаниях без трения энергия переходит из потенциальной в кинетическую и обратно. В крайней точке скорость равна нулю, а потенциальная энергия максимальна. В положении равновесия — наоборот: скорость максимальна, ускорение и возвращающая сила равны нулю.</p>
<div class="rule">$$E = \dfrac{kA^2}{2} = \dfrac{mv_{max}^2}{2} \quad\Rightarrow\quad v_{max} = A\sqrt{\dfrac{k}{m}} = A\omega$$</div>
<div class="example"><p><b>Пример.</b> Груз массой 0,25 кг на пружине жёсткостью 100 Н/м колеблется с амплитудой 4 см. $v_{max} = 0{,}04\cdot\sqrt{100/0{,}25} = 0{,}04\cdot 20 = 0{,}8$ м/с.</p></div>
<p><b>Резонанс</b> — резкое возрастание амплитуды вынужденных колебаний, когда частота внешней силы совпадает с собственной частотой системы.</p>`
        },
        {
          h: 'Волны и звук',
          html: String.raw`<p><b>Механическая волна</b> — распространение колебаний в упругой среде. Волна переносит энергию, но не вещество: частицы среды лишь колеблются около своих положений.</p>
<ul>
<li><b>Поперечные</b> волны — частицы колеблются перпендикулярно направлению распространения. Возможны только в твёрдых телах (и на поверхности жидкости).</li>
<li><b>Продольные</b> волны — колебания вдоль направления распространения (сжатия и разрежения). Возможны в газах, жидкостях и твёрдых телах. Звук в воздухе — продольная волна.</li>
</ul>
<div class="rule">$$\lambda = vT = \dfrac{v}{\nu}$$ Длина волны — расстояние, на которое волна распространяется за один период.</div>
<p><b>Звук</b> — упругие волны с частотой от 16–20 Гц до 20 кГц. Ниже — инфразвук, выше — ультразвук. <span class="hl">Высота тона определяется частотой, громкость — амплитудой.</span> Скорость звука в воздухе около 340 м/с, в воде около 1500 м/с. В вакууме звук не распространяется.</p>
<div class="trap">При переходе волны из одной среды в другую <b>частота не меняется</b> (её задаёт источник), меняются скорость и длина волны. Звук из воздуха в воду: скорость растёт, значит длина волны тоже растёт.</div>
<div class="tip">Эхо: звук проходит расстояние до преграды дважды, поэтому $s = \dfrac{vt}{2}$.</div>`
        }
