        {
          h: 'Тепловые явления: нагрев и агрегатные переходы',
          html: String.raw`<p>Внутреннюю энергию тела можно изменить двумя способами: совершив работу или путём теплопередачи. Виды теплопередачи: <b>теплопроводность</b> (без переноса вещества), <b>конвекция</b> (перенос потоками жидкости или газа, только в них) и <b>излучение</b> (возможно даже в вакууме — так греет Солнце).</p>
<div class="rule">
$$Q = cm\Delta t \qquad Q = \lambda m \qquad Q = Lm \qquad Q = qm$$
нагрев / плавление / парообразование / сгорание топлива
</div>
<ul>
<li>$c$ — удельная теплоёмкость (вода — 4200 Дж/(кг·°С));</li>
<li>$\lambda$ — удельная теплота плавления (лёд — $3{,}3\cdot 10^5$ Дж/кг);</li>
<li>$L$ — удельная теплота парообразования (вода — $2{,}3\cdot 10^6$ Дж/кг);</li>
<li>$q$ — удельная теплота сгорания топлива.</li>
</ul>
<div class="trap">Во время плавления и кипения температура <b>не меняется</b>, хотя тепло подводится: энергия идёт на разрушение связей между молекулами. На графике $t(\tau)$ это горизонтальные участки. Если лёд взят при $-10$ °С, сначала его нужно нагреть до 0 °С, и только потом плавить.</div>
<p><b>Уравнение теплового баланса</b>: в теплоизолированной системе отданное тепло равно полученному: $Q_{отд} = Q_{пол}$.</p>
<div class="example"><p><b>Пример.</b> Смешали 1 кг воды при 80 °С и 3 кг воды при 20 °С. $c\cdot 1\cdot(80 - t) = c\cdot 3\cdot(t - 20)$, откуда $80 - t = 3t - 60$, $t = 35$ °С.</p></div>`
        },
        {
          h: 'Основы МКТ',
          html: String.raw`<p>Вещество состоит из частиц, которые беспорядочно движутся и взаимодействуют. Доказательства — диффузия и броуновское движение.</p>
<ul>
<li>Количество вещества: $\nu = \dfrac{m}{M} = \dfrac{N}{N_A}$, $N_A = 6{,}02\cdot 10^{23}$ моль⁻¹.</li>
<li>Абсолютная температура: $T = t + 273$ (К). Абсолютный нуль — $-273$ °С.</li>
<li>Средняя кинетическая энергия поступательного движения молекулы: $\bar E_к = \dfrac{3}{2}kT$, $k = 1{,}38\cdot 10^{-23}$ Дж/К.</li>
<li>Давление газа: $p = nkT$, где $n = N/V$ — концентрация молекул.</li>
</ul>
<div class="trap">Изменение температуры на 1 °С равно изменению на 1 К. Но «температура увеличилась в 2 раза» — это только про кельвины: 27 °С = 300 К, вдвое больше — 600 К = 327 °С, а не 54 °С.</div>
<div class="quick" data-a="400">Какая абсолютная температура (в кельвинах) соответствует 127 °С?</div>`
        },
        {
          h: 'Идеальный газ и изопроцессы',
          html: String.raw`<div class="rule">Уравнение Менделеева — Клапейрона: $$pV = \nu RT = \dfrac{m}{M}RT, \qquad R = 8{,}31\ \dfrac{\text{Дж}}{\text{моль}\cdot\text{К}}$$</div>
<table class="tbl">
<tr><th>Процесс</th><th>Постоянно</th><th>Закон</th></tr>
<tr><td>Изотермический</td><td>$T$</td><td>$pV = \text{const}$ (Бойль — Мариотт)</td></tr>
<tr><td>Изобарный</td><td>$p$</td><td>$V/T = \text{const}$ (Гей-Люссак)</td></tr>
<tr><td>Изохорный</td><td>$V$</td><td>$p/T = \text{const}$ (Шарль)</td></tr>
</table>
<p>Законы справедливы при постоянной массе газа. Все температуры — только в кельвинах.</p>
<p><b>Влажность воздуха</b>: $\varphi = \dfrac{p}{p_{нас}}\cdot 100\%$. Насыщенный пар — пар в динамическом равновесии со своей жидкостью; его давление зависит только от температуры и не подчиняется газовым законам.</p>`
        },
        {
          h: 'Первый закон термодинамики и тепловые машины',
          html: String.raw`<div class="rule">$$Q = \Delta U + A$$ Теплота, переданная газу, идёт на изменение его внутренней энергии и на работу газа.</div>
<ul>
<li>Внутренняя энергия одноатомного идеального газа: $U = \dfrac{3}{2}\nu RT$ — зависит <b>только от температуры</b>.</li>
<li>Работа газа при постоянном давлении: $A = p\Delta V$; в общем случае — площадь под графиком $p(V)$.</li>
</ul>
<table class="tbl">
<tr><th>Процесс</th><th>Первый закон</th></tr>
<tr><td>Изохорный</td><td>$A = 0$, $Q = \Delta U$</td></tr>
<tr><td>Изотермический</td><td>$\Delta U = 0$, $Q = A$</td></tr>
<tr><td>Изобарный (одноатомный газ)</td><td>$Q = \dfrac{5}{2}\nu R\Delta T = \dfrac{5}{2}p\Delta V$</td></tr>
<tr><td>Адиабатный</td><td>$Q = 0$, $A = -\Delta U$: расширяясь, газ охлаждается</td></tr>
</table>
<p><b>Тепловая машина</b> получает $Q_1$ от нагревателя, отдаёт $Q_2$ холодильнику и совершает работу $A = Q_1 - Q_2$.</p>
<div class="rule">$$\eta = \dfrac{A}{Q_1} = \dfrac{Q_1 - Q_2}{Q_1} \qquad \eta_{Карно} = \dfrac{T_1 - T_2}{T_1}$$</div>
<div class="tip">КПД реальной машины всегда меньше КПД Карно при тех же температурах. Если в задаче получился КПД больше $\eta_{Карно}$ — такая машина невозможна, ищите ошибку.</div>`
        }
