          h: 'Волновая оптика',
          html: String.raw`<p><b>Дисперсия</b> — зависимость показателя преломления от частоты (цвета). Призма разлагает белый свет в спектр; сильнее всего преломляются фиолетовые лучи, слабее всего — красные. Длины волн видимого света: от 400 нм (фиолетовый) до 760 нм (красный).</p>
<p><b>Интерференция</b> — сложение когерентных волн. При разности хода $\Delta = k\lambda$ — максимум (усиление), при $\Delta = (2k + 1)\dfrac{\lambda}{2}$ — минимум (ослабление). Пример — радужные плёнки мыльных пузырей.</p>
<p><b>Дифракция</b> — огибание волнами препятствий, сравнимых с длиной волны.</p>
<div class="rule">Дифракционная решётка: $$d\sin\varphi = k\lambda, \qquad d = \dfrac{1\ \text{мм}}{N}$$ где $d$ — период решётки, $N$ — число штрихов на 1 мм, $k$ — порядок максимума.</div>
<div class="tip">Наибольший порядок: $k_{max}$ — целая часть от $d/\lambda$ (так как $\sin\varphi \le 1$). Всего на экране $2k_{max} + 1$ максимумов, считая центральный.</div>`
