          hint: String.raw`Разность показаний равна силе Архимеда. Объём тела найдите через его вес и плотность: $V = \dfrac{P}{\rho g}$.`,
          solution: String.raw`$F_A = 10 - 6{,}8 = 3{,}2$ Н. $m = 1$ кг, $V = \dfrac{m}{\rho} = \dfrac{1}{2500} = 4\cdot 10^{-4}$ м³. $\rho_ж = \dfrac{F_A}{gV} = \dfrac{3{,}2}{10\cdot 4\cdot 10^{-4}} = 800$ кг/м³ (например, керосин).`
