          solution: String.raw`Силы: $mg$ в середине лестницы, реакция стены $N_1$ (горизонтально), реакция пола $N_2$ (вверх) и трение $F_{тр}$ (к стене). По горизонтали: $F_{тр} = N_1$. Моменты относительно нижнего конца (длина $L$): $N_1L\sin\alpha = mg\dfrac{L}{2}\cos\alpha \Rightarrow N_1 = \dfrac{mg}{2\tg\alpha}$. При $45^\circ$: $F_{тр} = N_1 = \dfrac{100}{2\cdot 1} = 50$ Н.`
