          solution: String.raw`$T = \dfrac{30{,}0}{20} = 1{,}50$ с, $\Delta T = \dfrac{\Delta t}{N} = \dfrac{0{,}2}{20} = 0{,}01$ с. Результат: $T = (1{,}50 \pm 0{,}01)$ с. Именно поэтому измеряют время многих колебаний, а не одного — погрешность периода уменьшается.`
