      summary: 'Как считать количество теплоты при нагревании, плавлении и парообразовании и решать задачи на смешивание веществ по уравнению теплового баланса.',
      keyPoints: [
        String.raw`Нагрев и охлаждение: $Q = cm(t_2 - t_1)$`,
        String.raw`Плавление и кристаллизация: $Q = \lambda m$; парообразование и конденсация: $Q = Lm$ — температура при этом не меняется`,
        String.raw`Сгорание топлива: $Q = qm$; КПД $\eta = \dfrac{Q_{\text{полезная}}}{Q_{\text{затраченная}}}\cdot 100\%$`,
        String.raw`Тепловой баланс: $Q_{\text{отд}} = Q_{\text{пол}}$ (если потерь нет)`,
        String.raw`Табличные значения: $c_{\text{воды}} = 4200$, $c_{\text{льда}} = 2100$ Дж/(кг·°С), $\lambda_{\text{льда}} = 3{,}3\cdot 10^5$ Дж/кг, $L_{\text{воды}} = 2{,}3\cdot 10^6$ Дж/кг`,
        String.raw`Перед расчётом переведите граммы в килограммы`
      ],
      theory: [
        {
          h: 'Нагревание и охлаждение',
          html: String.raw`<p>Чтобы нагреть тело, ему нужно передать энергию. <b>Удельная теплоёмкость</b> $c$ — это теплота, необходимая, чтобы нагреть 1 кг вещества на 1 °С.</p>
<div class="rule">$$Q = cm(t_2 - t_1)$$ При нагревании $Q > 0$ (тело получает теплоту), при охлаждении $Q < 0$ (отдаёт). Для расчёта отданной теплоты берут модуль: $Q_{\text{отд}} = cm(t_1 - t_2)$.</div>
<p>У воды теплоёмкость очень большая — 4200 Дж/(кг·°С): поэтому вода медленно нагревается и медленно остывает, а металлы (сталь — 500, медь — 400) нагреваются быстро.</p>
<div class="trap">Масса — только в килограммах! 200 г = 0,2 кг. Разность температур $\Delta t$ в градусах Цельсия и в кельвинах одна и та же, а вот сами $t$ и $T$ различаются на 273.</div>
<div class="quick" data-a="42000">Сколько теплоты (в Дж) нужно, чтобы нагреть 0,5 кг воды на 20 °С?</div>`
        },
        {
          h: 'Плавление, кипение и график нагревания',
          html: String.raw`<p>Пока вещество плавится или кипит, подводимая теплота идёт на разрушение связей между частицами, а <b>температура остаётся постоянной</b> — на графике это горизонтальный участок.</p>
<div class="rule">Плавление (и кристаллизация): $Q = \lambda m$. Парообразование (и конденсация): $Q = Lm$. Здесь $\lambda$ и $L$ — удельные теплоты, Дж/кг.</div>
<div class="example"><p><b>Пример.</b> Сколько теплоты нужно, чтобы 1 кг льда при $-10\ ^\circ$С превратить в воду при $0\ ^\circ$С? Сначала нагрев льда: $2100\cdot 1\cdot 10 = 21\,000$ Дж, потом плавление: $3{,}3\cdot 10^5\cdot 1 = 330\,000$ Дж. Итого 351 кДж.</p></div>
<div class="trap">Нельзя считать «одной формулой» весь путь от льда до пара. Каждый участок графика — своя формула: $cm\Delta t$ на наклонных участках и $\lambda m$ или $Lm$ на горизонтальных.</div>
<div class="quick" data-a="660000">Сколько теплоты (в Дж) нужно, чтобы расплавить 2 кг льда при 0 °С? $\lambda = 3{,}3\cdot 10^5$ Дж/кг.</div>`
        },
        {
          h: 'Уравнение теплового баланса',
          html: String.raw`<p>Если тела обмениваются теплотой только друг с другом (в теплоизолированном сосуде), то сколько теплоты отдали горячие, столько же получили холодные.</p>
<div class="rule">$$Q_{\text{отд}} = Q_{\text{пол}} \qquad c_1m_1(t_1 - t) = c_2m_2(t - t_2)$$ Здесь $t$ — установившаяся температура, $t_1 > t > t_2$.</div>
<p>Для двух порций воды $c$ сокращается, и температура смеси — среднее, «взвешенное» по массам: $t = \dfrac{m_1t_1 + m_2t_2}{m_1 + m_2}$.</p>
<div class="example"><p><b>Пример.</b> Стальную деталь (4,2 кг, 100 °С) опустили в 0,5 кг воды при 20 °С. $c_ст = 500$. Пусть $t$ — итоговая температура. $500\cdot 4{,}2\,(100 - t) = 4200\cdot 0{,}5\,(t - 20)$, то есть $2100(100 - t) = 2100(t - 20)$. Отсюда $t = 60\ ^\circ$С.</p></div>
<div class="trap">Если в смеси есть лёд или пар, итоговая температура может оказаться ровно 0 °С или 100 °С — часть вещества не успеет расплавиться. Сначала проверьте, хватает ли теплоты для плавления всего льда, и только потом решайте уравнение.</div>
<div class="quick" data-a="50">Смешали 2 кг воды при 90 °С и 2 кг воды при 10 °С. Какой станет температура (в °С)?</div>`
        },
        {
          h: 'Топливо, нагреватели и КПД',
          html: String.raw`<p>При сгорании топлива выделяется $Q = qm$, где $q$ — удельная теплота сгорания (Дж/кг). У электронагревателя теплота равна работе тока: $Q = Pt$.</p>
<div class="rule">$$\eta = \dfrac{Q_{\text{полезная}}}{Q_{\text{затраченная}}}\cdot 100\%$$ Полезная теплота — та, что пошла на нагрев (воды, детали), затраченная — вся выделившаяся: $qm$ или $Pt$.</div>
<div class="example"><p><b>Пример.</b> Чайник мощностью 2100 Вт с КПД 80 % нагревает 1 кг воды от 20 до 100 °С. Полезная теплота: $4200\cdot 1\cdot 80 = 336\,000$ Дж. Затраченная: $Pt$. Из $\eta = 0{,}8$ получаем $Pt = 420\,000$ Дж, $t = 200$ с.</p></div>
<div class="trap">КПД всегда меньше 100 %. Если получилось больше — вы перепутали числитель и знаменатель.</div>
<div class="quick" data-a="40">Нагреватель получил 500 Дж, из них на полезную работу пошло 200 Дж. Найдите КПД в процентах.</div>`
        }
      ],
