          id: 'phys-heat-transfer-1', type: 'input', exam: 'oge', difficulty: 1,
          q: 'Какое количество теплоты необходимо, чтобы нагреть 2 кг воды на 10 °С? Удельная теплоёмкость воды 4200 Дж/(кг·°С).',
