          solution: String.raw`Абсолютная влажность $\rho = 0{,}5\cdot 17{,}3 = 8{,}65$ г/м³. Она меньше 9,4 г/м³, значит роса не выпадет и $\rho$ сохранится. При 10 °С: $\varphi = \dfrac{8{,}65}{9{,}4}\cdot 100\% \approx 92\%$.`
