          solution: String.raw`$t/T = 6/2 = 3$ периода. Останется $N = N_0\cdot 2^{-3} = \dfrac{8\cdot 10^{20}}{8} = 10^{20}$ ядер. Распадётся $N_0 - N = 8\cdot 10^{20} - 10^{20} = 7\cdot 10^{20}$ ядер.`
